use vstd::prelude::*;

verus! {
    // Copy a non‐empty vector of chars by traversing from start to end.
    // Loop invariant keeps track of how many characters have been copied
    // and that the copied prefix matches the input.
    fn solve(t: Vec<char>) -> Vec<char>
        requires
            // Input must be non‐empty
            t.len() >= 1
        ensures
            // The result has the same length as the input
            |res: Vec<char>| res.len() == t.len()
                // And for every index i < t.len(), res[i] == t[i]
                && forall |i: nat| i < (t.len() as nat) ==>
                     res.index(i) == t.index(i)
    {
        let n = t.len();
        // We'll build up this vector one character at a time.
        let mut out: Vec<char> = Vec::new();
        let mut idx: usize = 0;

        // Invariant explanations:
        //   1) idx <= n  
        //   2) out.len() == idx  
        //   3) for every i < idx, out[i] == t[i]
        // Decreases clause ensures termination: n - idx strictly shrinks.
        while idx < n
            invariant
                idx <= n,
                out.len() == idx,
                forall |i: nat| i < (idx as nat) ==>
                    out.index(i) == t.index(i),
            decreases
                n - idx
        {
            // Copy the character at position idx
            let c = t.index(idx as nat);
            out.push(c);
            idx = idx + 1;
        }

        out
    }
}

